function validate([money, children]) {
  if (!Number.isInteger(money) || money < 1 || money > 200) return 'money is a whole number from 1 to 200.';
  if (!Number.isInteger(children) || children < 2 || children > 30) return 'children is a whole number from 2 to 30.';
  return null;
}

