function distMoney(money, children) {
  // best[c][m]: most 8-dollar children when exactly m dollars go to c children under the rules.
  const best = Array.from({ length: children + 1 }, () => new Array(money + 1).fill(-Infinity));
  best[0][0] = 0;
  for (let c = 1; c <= children; c++) {
    for (let m = 0; m <= money; m++) {
      for (let give = 1; give <= m; give++) {
        if (give === 4 || best[c - 1][m - give] === -Infinity) continue;
        best[c][m] = Math.max(best[c][m], best[c - 1][m - give] + (give === 8 ? 1 : 0));
      }
    }
  }
  return best[children][money] === -Infinity ? -1 : best[children][money];
}

