function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const clamp = value => Math.max(1, Math.min(200, value));
  if (size === 'large') {
    const children = pick(2, 30);
    return [rand() < 0.5 ? pick(150, 200) : clamp(8 * children + pick(-8, 8)), children];
  }
  const children = pick(2, 6);
  const mode = rand();
  // Aim near the amounts where the rules bite: about 1 dollar each, or about 8 dollars each.
  if (mode < 0.3) return [clamp(children + pick(-2, 4)), children];
  if (mode < 0.75) return [clamp(8 * children + pick(-6, 6)), children];
  return [pick(1, 80), children];
}
